@Configuration
@EnableScheduling
class SchedulingConfiguration {}

@Component
class WeeklyDigestJob {
    private final WeeklyDigestService digests;

    WeeklyDigestJob(WeeklyDigestService digests) {
        this.digests = digests;
    }

    @Scheduled(cron = "0 0 9 * * SUN", zone = "Asia/Kolkata")
    void queueDigests() {
        digests.aggregateAndQueue();
    }
}
